const mongoose = require('mongoose');

const assessmentQuestionSchema = new mongoose.Schema(
  {
    topicSlug: {
      type: String,
      required: true
    },
    difficulty: {
      type: String,
      enum: ['Easy', 'Medium', 'Hard'],
      default: 'Easy'
    },
    type: {
      type: String,
      enum: [
        'mcq',
        'output_prediction',
        'complexity',
        'debugging',
        'code_completion',
        'pattern_id'
      ],
      required: true
    },
    question: {
      type: String,
      required: true
    },
    codeSnippet: {
      type: String,
      default: ''
    },
    options: [
      {
        text: String
      }
    ],
    correctOptionIndex: {
      type: Number,
      required: true
    },
    explanation: {
      type: String,
      required: true
    },
    points: {
      type: Number,
      default: 10
    }
  },
  { timestamps: true }
);

module.exports = mongoose.model('Assessment', assessmentQuestionSchema);
